tasks.starter:
function survivors(rows){
  return rows.filter(r =>
    r.status === 'active' || r.status === 'pending' && r.region === 'EU'
  );
}
this.survivors = survivors;

tasks.verify:
const rows=[{status:'active',region:'US'},{status:'active',region:'EU'},{status:'pending',region:'EU'},{status:'pending',region:'US'},{status:'closed',region:'EU'}];
const out=survivors(rows);
const keys=out.map(r=>r.status+':'+r.region).sort().join('|');
const ok = keys==='active:EU|pending:EU';
console.log(ok ? 'PASS' : 'FAIL got='+keys);
